// [MEDIUM_PRIORITY] PERFORMANCE: String Concatenation optimized
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.executionimport com.roshan.persona.cognitive.model.CognitiveConfigimport com.roshan.persona.cognitive.model.ReasoningTraceimport com.roshan.persona.common.CorrelationIdimport java.util.concurrent.ConcurrentHashMap/** * NOUS — Reasoning Cache (Module 7 v2 — Step 7.7, P1). * * Caches reasoning traces to skip redundant LLM calls. If the user asks the * same query twice within 7 days, the cached trace is returned instantly * (< 50ms) instead of re-running the full reasoning pipeline (< 20s). * * ## Cache key * * The key is `(queryHash, userId)` — the query is normalized (lowercased, * trimmed, whitespace-collapsed) and hashed to produce a compact key. This * ensures "Plan a Goa trip" and "plan a goa trip" hit the same cache entry. * * ## TTL * * Default 7 days (per [CognitiveConfig.cacheTtlDays]). After TTL expires, * the entry is evicted on next lookup. * * ## Eviction * * LRU (Least Recently Used) — when the cache exceeds * [CognitiveConfig.maxCachedTraces] (default 100), the oldest entry is * evicted. * * ## v1 storage * * In-memory (ConcurrentHashMap). Resets on app restart. v3+ will use Room * for persistence across restarts. * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§ReasoningCache</a> */class ReasoningCache(    private val config: CognitiveConfig = CognitiveConfig(),) {    /** Cache entry: trace + insertion timestamp + last-access timestamp (for LRU). */    private data class CacheEntry(        val trace: ReasoningTrace,        val insertedMs: Long,        var lastAccessedMs: Long,    )    private val cache = ConcurrentHashMap<String, CacheEntry>()    /**     * Look up a cached trace for (query, userId).     *     * @param query the user's query.     * @param userId the user's ID.     * @param nowMs current epoch time (injectable for testing).     * @return the cached trace, or null if not cached or expired.     */    fun lookup(query: String, userId: String, personaId: String = "default", nowMs: Long = System.currentTimeMillis()): ReasoningTrace? {        val key = buildKey(query, userId, personaId)        val entry = cache[key] ?: return null        // Check TTL.        val ttlMs = config.cacheTtlDays * 24L * 60 * 60 * 1000        if (nowMs - entry.insertedMs > ttlMs) {            cache.remove(key)            return null        }        // Update last-accessed for LRU.        entry.lastAccessedMs = nowMs        return entry.trace    }    /**     * Store a trace for future lookup.     *     * @param query the user's query.     * @param userId the user's ID.     * @param trace the reasoning trace to cache.     * @param nowMs current epoch time (injectable for testing).     */    fun store(query: String, userId: String, trace: ReasoningTrace, personaId: String = "default", nowMs: Long = System.currentTimeMillis()) {        val key = buildKey(query, userId, personaId)        cache[key] = CacheEntry(            trace = trace,            insertedMs = nowMs,            lastAccessedMs = nowMs,        )        // LRU eviction if over capacity.        if (cache.size > config.maxCachedTraces) {            evictOldest()        }    }    /**     * Check if a cache entry exists and is not expired.     *     * Faster than [lookup] — doesn't update last-accessed or return the trace.     */    fun has(query: String, userId: String, personaId: String = "default", nowMs: Long = System.currentTimeMillis()): Boolean {        val key = buildKey(query, userId, personaId)        val entry = cache[key] ?: return false        val ttlMs = config.cacheTtlDays * 24L * 60 * 60 * 1000        return nowMs - entry.insertedMs <= ttlMs    }    /** Clear all cached traces. */    fun clear() {        cache.clear()    }    /** Number of cached entries (including expired — call [cleanup] first for accurate count). */    fun size(): Int = cache.size    /** Remove expired entries. */    fun cleanup(nowMs: Long = System.currentTimeMillis()) {        val ttlMs = config.cacheTtlDays * 24L * 60 * 60 * 1000        val iterator = cache.entries.iterator()        while (iterator.hasNext()) {            val entry = iterator.next()            if (nowMs - entry.value.insertedMs > ttlMs) {                iterator.remove()            }        }    }    /** Evict the oldest entry (by lastAccessedMs). */    private fun evictOldest() {        val oldest = cache.minByOrNull { it.value.lastAccessedMs }        if (oldest != null) {            cache.remove(oldest.key)        }    }    /**     * Build a cache key from (query, userId, personaId).     *     * Audit fix: previously omitted personaId — same user, same query, two     * personas would return the first persona's cached trace. Now persona     * is part of the key per strategy §8: `hash(query + userId + persona)`.     */    private fun buildKey(query: String, userId: String, personaId: String = "default"): String {        val normalized = query.lowercase().trim().replace(Regex("\\s+"), " ")        return "$userId::$personaId::${normalized.hashCode()}"    }}